Problem:
A woman with vitamin deficiency is taking supplements from two brands, super vitamin XYZ and vitamin ABC. Super vitamin XYZ contains 2 mg of vitamin, 5 mg of fiber, and causes 2 units of drowsiness per serving. Vitamin ABC contains 1.5 mg of vitamin, 3 mg of fiber, and causes 3 units of drowsiness per serving. The woman wants to get at least 30 mg of vitamin and 55 mg of fiber. In addition, there must be at most 40% of the supplements taken from super vitamin XYZ and there must be at least 3 servings of super vitamin XYZ because it is expiring soon. How many servings of each should she take to minimize her total drowsiness.

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "servings of super vitamin XYZ",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "servings of vitamin ABC",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "servings of super vitamin XYZ",
     "coef": 2.0
    },
    {
     "var": "servings of vitamin ABC",
     "coef": 3.0
    }
   ]
  },
  "constraints": [
   {
    "name": "vitamin_requirement",
    "terms": [
     {
      "var": "servings of super vitamin XYZ",
      "coef": 2.0
     },
     {
      "var": "servings of vitamin ABC",
      "coef": 1.5
     }
    ],
    "sense": ">=",
    "rhs": 30.0
   },
   {
    "name": "fiber_requirement",
    "terms": [
     {
      "var": "servings of super vitamin XYZ",
      "coef": 5.0
     },
     {
      "var": "servings of vitamin ABC",
      "coef": 3.0
     }
    ],
    "sense": ">=",
    "rhs": 55.0
   },
   {
    "name": "xyz_share_max",
    "terms": [
     {
      "var": "servings of super vitamin XYZ",
      "coef": 0.6
     },
     {
      "var": "servings of vitamin ABC",
      "coef": -0.4
     }
    ],
    "sense": "<=",
    "rhs": 0.0
   },
   {
    "name": "xyz_minimum",
    "terms": [
     {
      "var": "servings of super vitamin XYZ",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 3.0
   }
  ]
 },
 "facts": {
  "objective": 47.0,
  "values": {
   "servings of super vitamin XYZ": 7.0,
   "servings of vitamin ABC": 11.0
  },
  "binding": [],
  "slack": {
   "vitamin_requirement": 0.5,
   "fiber_requirement": 13.0,
   "xyz_share_max": 0.2,
   "xyz_minimum": 4.0
  },
  "shadow_prices": null
 }
}
